{
  "steps": [
    {
      "title": "შეავსე ბიურეტი",
      "text": "ონკანი დახურულია? ძაბრით ჩაასხი ტიტრანტი ნულოვან ნიშნულზე ოდნავ მაღლა.",
      "focus": ["p4", "p1", "p2"],
      "avoid": ["p3"],
      "markers": [
        {"part": "p4", "label": "შეამოწმე, რომ დახურულია", "tone": "brand"},
        {"part": "p1", "label": "ტიტრანტი ჩაასხი აქ", "tone": "brand"}
      ],
      "arrows": [],
      "tools": ["დამცავი სათვალე", "შესაფერისი დამცავი ხელთათმანები"],
      "warn": "ფოტოთი ონკანის დახურულობა და ნულოვანი ნიშნული ვერ დასტურდება; ადგილზე გადაამოწმე. გამოიყენე მხოლოდ პროტოკოლით განსაზღვრული ტიტრანტი."
    },
    {
      "title": "მოხსენი ძაბრი",
      "text": "ძაბრი ტიტრაციამდე აუცილებლად მოხსენი. მისგან ჩამოსული წვეთები მოცულობას გააფუჭებს.",
      "focus": ["p1"],
      "avoid": ["p3"],
      "markers": [
        {"part": "p1", "label": "მოსახსნელი ძაბრი", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p1", "type": "move", "dir": "up"}
      ],
      "tools": [],
      "warn": "ძაბრი ფრთხილად ამოიღე, ბიურეტის დამაგრების შეუცვლელად."
    },
    {
      "title": "წაიკითხე საწყისი მოცულობა",
      "text": "თვალი სითხის დონეზე დაიჭირე და წაიკითხე მენისკის ქვედა კიდე. ჩაიწერე ჟურნალში.",
      "focus": ["p2"],
      "avoid": ["p4", "p3"],
      "markers": [
        {"part": "p2", "label": "მენისკის წაკითხვა თვალის დონეზე", "tone": "brand"}
      ],
      "arrows": [],
      "tools": ["ლაბორატორიული ჟურნალი", "კალამი"],
      "warn": "ფოტოზე ზუსტი მოცულობა არ იკითხება. საწყისი ჩვენების ჩაწერამდე დარწმუნდი, რომ ბიურეტის წვერი სითხითაა შევსებული და ჰაერის ბუშტები არ არის."
    },
    {
      "title": "დაამატე ინდიკატორი",
      "text": "კოლბაში ჩააწვეთე 2–3 წვეთი ფენოლფთალეინი და დადე თეთრ ფილაზე ონკანის ქვეშ.",
      "focus": ["p6", "p5", "p7"],
      "avoid": ["p4", "p3"],
      "markers": [
        {"part": "p6", "label": "ინდიკატორის საწვეთური", "tone": "brand"},
        {"part": "p5", "label": "ჩააწვეთე კოლბაში", "tone": "brand"},
        {"part": "p7", "label": "კოლბის დასადგმელი ფილა", "tone": "neutral"}
      ],
      "arrows": [],
      "tools": [],
      "warn": "ბოთლის შიგთავსი ფოტოთი ვერ დასტურდება — გადაამოწმე ეტიკეტი. 2–3 წვეთი მოცემული ინსტრუქციის დოზაა და არა ფოტოდან დადგენილი. კოლბა ფოტოზე უკვე ფილაზე დგას."
    },
    {
      "title": "ტიტრაცია",
      "text": "ონკანი ნელა გახსენი და კოლბა წრიულად ატრიალე. გაჩერდი, როცა ღია ვარდისფერი 30 წამს შენარჩუნდება.",
      "focus": ["p4", "p5"],
      "avoid": ["p3"],
      "markers": [
        {"part": "p4", "label": "აკონტროლე წვეთების მიწოდება", "tone": "brand"},
        {"part": "p5", "label": "მსუბუქად ატრიალე და დააკვირდი ფერს", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p5", "type": "rotate", "dir": "cw"}
      ],
      "tools": ["ტაიმერი"],
      "warn": "ონკანის გახსნის მიმართულება ფოტოდან არ განისაზღვრება; ძალა არ დაატანო. კოლბა ბიურეტის წვერს არ მიარტყა. საბოლოო წერტილთან ტიტრანტი წვეთობით დაამატე და მითითებული ფერის შენარჩუნებისას ონკანი დახურე; ეს კრიტერიუმი შენს პროტოკოლს უნდა შეესაბამებოდეს."
    }
  ],
  "unknown_parts": []
}
